use acer_device::Device;
use acer_protocol::{backlight_frame_ack,backlight_frame_matches,dynamic_restore_plan,dynamic_trial_frame,dynamic_trial_matches,lighting_call_ack,observed_backlight_frame,ApplyReport,ApplyStatus,BacklightFrame,Capabilities,DeviceError,LightingEffect,Snapshot,DYNAMIC_TRIAL_COLOR};
use serde::Serialize;use crate::validation::Outcome;
#[derive(Serialize)]pub struct Report{command:&'static str,target_effect:LightingEffect,target_code:u8,target_speed:u8,target_brightness:u8,target_direction:u8,color_when_used:[u8;3],outcome:Outcome,message:String,capabilities:Option<Capabilities>,original_frame:Option<BacklightFrame>,initial_snapshot:Option<Snapshot>,trial_apply:Option<ApplyReport>,target_snapshot:Option<Snapshot>,target_readback_confirmed:bool,restore_attempted:bool,restore_apply:Option<ApplyReport>,restored_snapshot:Option<Snapshot>,restore_readback_confirmed:bool,errors:Vec<(&'static str,DeviceError)>}
impl Report{pub fn success(&self)->bool{self.outcome==Outcome::ReadbacksConfirmed}fn new(effect:LightingEffect)->Self{Self{command:"--validate-lighting-effect",target_effect:effect,target_code:effect.code(),target_speed:3,target_brightness:20,target_direction:1,color_when_used:DYNAMIC_TRIAL_COLOR,outcome:Outcome::Rejected,message:String::new(),capabilities:None,original_frame:None,initial_snapshot:None,trial_apply:None,target_snapshot:None,target_readback_confirmed:false,restore_attempted:false,restore_apply:None,restored_snapshot:None,restore_readback_confirmed:false,errors:vec![]}}fn finish(mut self,message:&str)->Self{self.message=message.into();self}}
trait DynamicDevice{fn capabilities(&mut self)->Result<Capabilities,DeviceError>;fn snapshot(&mut self)->Result<Snapshot,DeviceError>;fn effect(&mut self,target:LightingEffect)->Result<ApplyReport,DeviceError>;fn restore(&mut self)->Result<ApplyReport,DeviceError>;fn settle(&mut self);}
struct Native<'a>(&'a Device);impl DynamicDevice for Native<'_>{fn capabilities(&mut self)->Result<Capabilities,DeviceError>{self.0.capabilities()}fn snapshot(&mut self)->Result<Snapshot,DeviceError>{self.0.snapshot()}fn effect(&mut self,target:LightingEffect)->Result<ApplyReport,DeviceError>{self.0.begin_dynamic_lighting_validation(target)}fn restore(&mut self)->Result<ApplyReport,DeviceError>{self.0.restore_validation_dynamic_lighting()}fn settle(&mut self){std::thread::sleep(std::time::Duration::from_secs(2));}}
pub fn run(device:&Device,effect:LightingEffect)->Report{validate(&mut Native(device),effect)}
fn validate(device:&mut impl DynamicDevice,effect:LightingEffect)->Report{
    let mut report=Report::new(effect);let Some(frame)=dynamic_trial_frame(effect)else{return report.finish("Static0 already validated; only dynamic targets1..7 are allowed");};
    let caps=match device.capabilities(){Ok(c)=>c,Err(e)=>{report.errors.push(("capabilities",e));return report.finish("Cannot verify device; no write attempted");}};let target=caps.matched_model&&acer_device::verified_fan_target(&caps.model,&caps.bios);report.capabilities=Some(caps);if !target{return report.finish("Requires PHN16-71/V1.18; no write attempted");}
    let before=match device.snapshot(){Ok(s)=>s,Err(e)=>{report.errors.push(("initial_read",e));return report.finish("Initial read failed; no write attempted");}};report.original_frame=observed_backlight_frame(&before);report.initial_snapshot=Some(before);
    if !report.original_frame.as_ref().is_some_and(|f|dynamic_restore_plan(f).is_some()){return report.finish("Original static0 frame and all four zones must be safely restorable; no write attempted");}
    let trial_ok=match device.effect(effect){Ok(r)=>{if let Some(f)=r.before.as_ref().and_then(observed_backlight_frame){report.original_frame=Some(f);}let ok=!matches!(r.status,ApplyStatus::Failed|ApplyStatus::Rejected)&&r.writes.len()==1&&backlight_frame_ack(&r.writes[0],&frame)==Some(true);report.trial_apply=Some(r);ok},Err(e)=>{report.errors.push(("effect_write",e));false}};
    if trial_ok{device.settle();match device.snapshot(){Ok(s)=>{report.target_readback_confirmed=dynamic_trial_matches(&s,effect);report.target_snapshot=Some(s);},Err(e)=>report.errors.push(("effect_read",e)),}}
    report.restore_attempted=true;let saved=report.original_frame.as_ref().unwrap();let calls=dynamic_restore_plan(saved).unwrap();
    let restore_ok=match device.restore(){Ok(r)=>{let ok=!matches!(r.status,ApplyStatus::Failed|ApplyStatus::Rejected)&&r.writes.len()==calls.len()&&calls.iter().zip(&r.writes).all(|(c,r)|lighting_call_ack(c,r)==Some(true));report.restore_apply=Some(r);ok},Err(e)=>{report.errors.push(("restore_write",e));false}};
    match device.snapshot(){Ok(s)=>{report.restore_readback_confirmed=restore_ok&&backlight_frame_matches(&s,saved,saved.observed_state[2]);report.restored_snapshot=Some(s);},Err(e)=>report.errors.push(("restored_read",e)),}
    report.outcome=if !report.restore_readback_confirmed{Outcome::RestoreUnconfirmed}else if trial_ok&&report.target_readback_confirmed&&report.errors.is_empty(){Outcome::ReadbacksConfirmed}else{Outcome::Failed};let message=if report.success(){"One dynamic configuration readback confirmed and original static frame/four zones restored; ignored color/direction fields are not treated as failed meaningful parameters"}else if report.restore_readback_confirmed{"Dynamic target unconfirmed or failed; original static frame and four zones confirmed"}else{"Original lighting restore remains unconfirmed; inspect the static-stop, four zones and final original-frame writes"};report.finish(message)
}
#[cfg(test)]mod tests{
    use super::*;use acer_protocol::{backlight_frame_call,ErrorKind,RawRead,RawValue};use std::collections::{BTreeMap,VecDeque};
    fn snapshot(effect:LightingEffect)->Snapshot{let mut s:Snapshot=serde_json::from_str(include_str!("../../../crates/acer-protocol/tests/fixtures/phn16-71-elevated-read.json")).unwrap();s.lighting_effect=Some(effect);if effect!=LightingEffect::Static{let frame=dynamic_trial_frame(effect).unwrap();let r=s.reads.iter_mut().find(|r|r.method=="GetGamingKBBacklight").unwrap();r.output.insert("gmOutput".into(),RawValue::Bytes(frame[..15].to_vec()));s.lighting=None;}s}
    fn applied(effect:LightingEffect,restore:bool)->ApplyReport{let calls=if restore{dynamic_restore_plan(&observed_backlight_frame(&snapshot(LightingEffect::Static)).unwrap()).unwrap()}else{vec![backlight_frame_call(dynamic_trial_frame(effect).unwrap())]};ApplyReport{status:ApplyStatus::Unconfirmed,message:"fake".into(),before:Some(snapshot(LightingEffect::Static)),after:None,writes:calls.into_iter().map(|c|RawRead{class:c.class,method:c.method,input:c.input,output:BTreeMap::from([("gmOutput".into(),RawValue::unsigned(0))]),error:None}).collect()}}
    fn error()->DeviceError{DeviceError{kind:ErrorKind::Transport,message:"fake failure".into()}}
    struct Fake{reads:VecDeque<Result<Snapshot,DeviceError>>,trial:Option<Result<ApplyReport,DeviceError>>,restore:Option<Result<ApplyReport,DeviceError>>,calls:Vec<&'static str>}
    impl Fake{fn new(effect:LightingEffect)->Self{Self{reads:[Ok(snapshot(LightingEffect::Static)),Ok(snapshot(effect)),Ok(snapshot(LightingEffect::Static))].into(),trial:Some(Ok(applied(effect,false))),restore:Some(Ok(applied(effect,true))),calls:vec![]}}}
    impl DynamicDevice for Fake{fn capabilities(&mut self)->Result<Capabilities,DeviceError>{Ok(Capabilities{model:"PHN16-71".into(),bios:"V1.18".into(),matched_model:true,items:vec![]})}fn snapshot(&mut self)->Result<Snapshot,DeviceError>{self.calls.push("read");self.reads.pop_front().unwrap()}fn effect(&mut self,_:LightingEffect)->Result<ApplyReport,DeviceError>{self.calls.push("effect");self.trial.take().unwrap()}fn restore(&mut self)->Result<ApplyReport,DeviceError>{self.calls.push("restore");self.restore.take().unwrap()}fn settle(&mut self){self.calls.push("settle");}}
    #[test]fn each_of_seven_simulated_configs_has_its_own_restore(){for code in 1..8{let effect=LightingEffect::from_code(code).unwrap();let mut f=Fake::new(effect);let r=validate(&mut f,effect);assert!(r.success());assert_eq!(r.target_code,code);assert_eq!(r.restore_apply.unwrap().writes.len(),6);assert_eq!(f.calls,["read","effect","settle","read","restore","read"]);}}
    #[test]fn static0_is_not_retested(){let mut f=Fake::new(LightingEffect::Wave);let r=validate(&mut f,LightingEffect::Static);assert_eq!(r.outcome,Outcome::Rejected);assert!(f.calls.is_empty());}
    #[test]fn effect_write_failure_still_attempts_restore(){let mut f=Fake::new(LightingEffect::Wave);f.trial=Some(Err(error()));f.reads.remove(1);let r=validate(&mut f,LightingEffect::Wave);assert_eq!(r.outcome,Outcome::Failed);assert!(r.restore_attempted&&r.restore_readback_confirmed);}
    #[test]fn effect_read_failure_still_restores(){let mut f=Fake::new(LightingEffect::Breathing);f.reads[1]=Err(error());let r=validate(&mut f,LightingEffect::Breathing);assert_eq!(r.outcome,Outcome::Failed);assert!(r.restore_readback_confirmed);}
    #[test]fn wrong_speed_is_not_a_confirmed_target(){let mut f=Fake::new(LightingEffect::Breathing);if let Some(RawValue::Bytes(b))=f.reads[1].as_mut().unwrap().reads.iter_mut().find(|r|r.method=="GetGamingKBBacklight").unwrap().output.get_mut("gmOutput"){b[1]=2;}let r=validate(&mut f,LightingEffect::Breathing);assert_eq!(r.outcome,Outcome::Failed);assert!(r.restore_readback_confirmed);}
    #[test]fn truncated_restore_is_unconfirmed_even_if_snapshot_matches(){let mut f=Fake::new(LightingEffect::Neon);f.restore.as_mut().unwrap().as_mut().unwrap().writes.truncate(5);let r=validate(&mut f,LightingEffect::Neon);assert_eq!(r.outcome,Outcome::RestoreUnconfirmed);assert!(r.restore_attempted);}
}
